INSERT INTO `broadcast_text` (`Text`,`Text1`,`ID`,`LanguageID`,`ConditionID`,`EmotesID`,`Flags`,`ChatBubbleDurationMs`,`VoiceOverPriorityID`,`SoundKitID1`,`SoundKitID2`,`EmoteID1`,`EmoteID2`,`EmoteID3`,`EmoteDelay1`,`EmoteDelay2`,`EmoteDelay3`,`VerifiedBuild`) VALUES
('Да, |3-6($c)?','',246152,0,0,0,0,0,4,0,0,0,0,0,0,0,0,70338),
('Здравствуй! Рад встрече.$B$BУвы, я с печальными вестями: Даларан нуждается в помощи королевств Альянса.','',299683,0,0,0,256,0,4,0,0,1,0,0,0,0,0,70425),
('','Чего тебе? Я довольно занята.',299856,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('Что ты хочешь найти?','Что ты хочешь найти?',300368,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('Я могу тебе чем-нибудь помочь?','Я могу тебе чем-нибудь помочь?',300369,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('','Что-то не так... Почему нет взрыва?',301833,0,0,1154,256,0,4,0,0,0,0,0,0,0,0,70425),
('Взрыва не будет. Я дал тебе нерабочий детонатор.','',301834,0,0,1,256,0,4,0,0,0,0,0,0,0,0,70425),
('','Что? Почему?',301835,0,0,1154,256,0,4,0,0,0,0,0,0,0,0,70425),
('Теперь этим займется ШРУ. Освобожденная у Братства Справедливости кузня и корабль обладают стратегической важностью. Мы берем их под свой контроль.','',301836,0,0,1,256,0,4,0,0,0,0,0,0,0,0,70425),
('','Ты не понимаешь. Эта кузня отравляет фермы Западного Края! Если ее не уничтожить, тут несколько поколений ничего не будет расти. Народ останется без пищи!',301837,0,0,1155,256,0,4,0,0,0,0,0,0,0,0,70425),
('Благодарю за беспокойство, эльф, но теперь это внутреннее дело Штормграда. Твоя помощь больше не нужна.','',301838,0,0,274,256,0,4,0,0,0,0,0,0,0,0,70425),
('А-а, ну ладно. Я... Я буду тут, если потом передумаешь. С-спасибо, что заходишь поболтать!','',303584,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70338),
('На сегодня боев не назначено. Орда и Альянс убивают друг друга по полям бесплатно, а могли бы на моей арене за хороший гонорар! Поди их пойми.\r\n\r\nЗайдешь попозже. Когда дела живее пойдут.','',309779,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('Осквернители! Негодяи! Убирайтесь отсюда!','',310791,0,0,0,256,0,4,340212,0,0,0,0,0,0,0,70425),
('Программа по сбору добычи запущена.','',310793,0,0,0,256,0,4,340209,0,0,0,0,0,0,0,70425),
('Возвращаюсь... ко сну...','',310794,0,0,0,256,0,4,340226,0,0,0,0,0,0,0,70425),
('Огонь пожирает все!','',310795,0,0,0,256,0,4,340200,0,0,0,0,0,0,0,70425),
('Что, хотите остановить величайшее ограбление в истории?','',310796,0,0,0,256,0,4,340210,0,0,0,0,0,0,0,70425),
('У меня все... почти... получилось.','',310797,0,0,0,256,0,4,340215,0,0,0,0,0,0,0,70425),
('Слава тебя опережает, |3-6($c). Если хочешь, я перепишу историю твоих подвигов заново.','Слава тебя опережает, |3-6($c). Если хочешь, я перепишу историю твоих подвигов заново.',311553,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70338),
('Слова подобны стрелам. Если выпустишь их, то уже не вернешь назад.','Слова подобны стрелам. Если выпустишь их, то уже не вернешь назад.',316796,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70338),
('','If you\'re looking for plate armor, mail armor or shields, I\'ve got the finest in all of Undercity. Most of these pieces are made and repaired here locally, though some are scavenged.\r\n\r\nFeel free to browse.',319820,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70338),
('Меня пригласили в Даларан как представителя Круга Кенария. Я нахожу этот город чудесным, но в то же время пугающим.\r\n\r\nА ты, новопосвященный друид, – если еще не знаешь Шельдраса Лунное Древо, отправляйся в Штормград и найди его. Он покажет тебе, как связаться с анклавом Круга Кенария на Лунной поляне.','Меня пригласили в Даларан как представителя Круга Кенария. Я нахожу этот город чудесным, но в то же время пугающим.\r\n\r\nА ты, новопосвященный друид, – если еще не знаешь Шельдраса Лунное Древо, отправляйся в Штормград и найди его. Он покажет тебе, как связаться с анклавом Круга Кенария на Лунной поляне.',320480,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<Голова Отмара смотрит на вас.>\r\n\r\nЧто... нужно...\r\n\r\n|3-6($r)... Мерзкая... тварь...','<Голова Отмара смотрит на вас.>\r\n\r\nЧто... нужно...\r\n\r\n|3-6($r)... Мерзкая... тварь...',321558,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70338),
('','Для тебя – "великая небовидица", маг. Уходи. Беги к своему господину, пока я совсем не потеряла терпение.',324557,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70338),
('Добро пожаловать в Стальгорн, |3-6($c).','',325813,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('','А, $n. Рада тебя видеть. Ты теперь дорогой гость в наших стенах.\r\n\r\nРасполагайся как дома. Даларан отплатит тебе за помощь, чем сможет.',327175,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('','<Когда вы приближаетесь, огромная кошка вытягивает длинные изящные лапы, не издавая ни звука.>',327777,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<Этикетка на механодолгоноге:\r\n\r\nСкороног "4в4рия" 3X 4000! Теперь с новыми датчиками радиации и распылителями для дезактивации!>','',327783,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('Как представителю Высшего ордена шен\'дорай тебе всегда рады в нашем городе, |3-6($c). \r\n\r\nВ последние месяцы мы с вашим лидером, Элаадрином Вечерняя Буря, вели оживленную переписку. Мне кажется, что Кирин-Тор и Высший орден – словно две стороны одной медали: мы всегда стремимся разгадать великие тайны мироздания. И сейчас, как никогда прежде, поиск ответов жизненно важен для всех нас.\r\n\r\nПодобно тому, как на Зефрисе был нарушен ваш привычный уклад, потоки магии на всем Азероте стали крайне нестабильны. Словно их что-то потревожило... Как если бы в спокойную воду бросили камень и по поверхности от этого пошли круги.\r\n\r\nВпрочем, разговоры об этих бедах подождут. А пока позволь приветствовать тебя на Азероте.','',327795,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<Ящер поворачивается и устремляет на вас взгляд ярко-оранжевых глаз.>','',327796,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<Даже сквозь забрало шлема вы чувствуете, как волк изучает вас взглядом.>','<Волк оборачивается, когда вы подходите. Вы ощущаете на себе взгляд его внимательных глаз, скрытых под забралом шлема. Зверь осторожно обнюхивает вас и, узнав, издает тихое, но вполне дружелюбное урчание.\r\n\r\n\r\nОн выпрямляется, словно желая продемонстрировать тяжелую броню, облачающую его мощное тело. Полированный металл блестит, несмотря на слой дуротарской пыли, нанесенной на него теплыми ветрами.\r\n\r\nВы испытываете необъяснимый прилив чувств, видя, что волку пришлась по нраву ваша отвага. Этот зверь готов обрести в вас наездника и верного друга.>',327804,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<При вашем приближении волк встряхивает своей крупной головой. Его доспехи мягко поблескивают, выделяясь на фоне пепельной шерсти зверя.>','',327805,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<Волк стоит, уверенно выпрямившись даже под тяжестью доспехов.>','<Подобно тому, как свежесрубленная кедровая древесина со временем меняет цвет с красноватого на серый, так и шерсть этого лесного волка изменилась с возрастом. Его некогда неуемный нрав стал более сдержанным, а взгляд сосредоточенным. Он уверенно и крепко стоит на ногах, и даже тяжелые доспехи, похоже, не доставляют ему неудобства.\r\n\r\nКогда вы подходите ближе, он дружелюбно помахивает длинным хвостом и приветственно поскуливает. В прорези укрепленного магией забрала шлема вы видите блеск его решительных глаз – жажда приключений в нем ничуть не угасла.\r\n\r\nЧерез мгновение волк принимается воодушевленно рычать. Вы чувствуете, что он восхищается вашим духом искателя приключений и впечатлен испытаниями, которые вы преодолели. Волк готов с радостью принять вас как всадника и верного спутника.>',327806,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('Ага, в таверне сидит гостья с Заоблачного пика. Она наверняка поможет тебе с духовными наставлениями... или чем там еще занимаются шаманы. Как же ее зовут?.. Ингол? Ир... Ингрид! Да, ее имя – Ингрид.','Ага, в таверне сидит гостья с Заоблачного пика. Она наверняка поможет тебе с духовными наставлениями... или чем там еще занимаются шаманы. Как же ее зовут?.. Ингол? Ир... Ингрид! Да, ее имя – Ингрид.',327809,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('А, подстричься хочешь? Мне бы к цирюльнику тоже сходить не помешало. Может, загляну после смены!\r\n\r\nПарикмахерская находится к северо-западу от входа в Стальгорн.','А, подстричься хочешь? Мне бы к цирюльнику тоже сходить не помешало. Может, загляну после смены!\r\n\r\nПарикмахерская находится к северо-западу от входа в Стальгорн.',328220,0,0,0,257,0,4,0,0,1,0,0,0,0,0,70425),
('Не волнуйся, парикмахерская совсем рядом – к северо-западу от входа в Стальгорн.\r\n\r\nТам тебя мигом приведут в порядок!','Не волнуйся, парикмахерская совсем рядом – к северо-западу от входа в Стальгорн.\r\n\r\nТам тебя мигом приведут в порядок!',328221,0,0,0,257,0,4,0,0,1,0,0,0,0,0,70425),
('Хочешь обновить узоры на лице или подготовиться к охоте? Лучшего места, чем парикмахерская, для этого не найти.\r\n\r\nОна расположена на Террасе Торговцев, рядом с аукционом.','Хочешь обновить узоры на лице или подготовиться к охоте? Лучшего места, чем парикмахерская, для этого не найти.\r\n\r\nОна расположена на Террасе Торговцев, рядом с аукционом.',328240,0,0,0,256,0,4,0,0,1143,0,0,0,0,0,70425),
('Прежде чем входить в храм, нужно привести себя в порядок. Загляни в парикмахерскую – она на Террасе Торговцев.','Прежде чем входить в храм, нужно привести себя в порядок. Загляни в парикмахерскую – она на Террасе Торговцев.',328241,0,0,0,256,0,4,0,0,1143,0,0,0,0,0,70425),
('Рога затупились? На нижнем ярусе центральной вершины есть гоблин, который тебе поможет.','Рога затупились? На нижнем ярусе центральной вершины есть гоблин, который тебе поможет.',328287,0,0,0,256,0,4,0,0,1143,0,0,0,0,0,70425),
('<Изнуренный человек бормочет себе под нос что-то неразборчивое.>','<Изнуренный человек бормочет себе под нос что-то неразборчивое.>',328594,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425),
('<Неподвижно лежащее тело Дикого бога прозрачно и неосязаемо, словно вот-вот растворится в воздухе. Когда вы подходите ближе, бог слегка вздрагивает и начинает следить за вами стекленеющим взглядом.>','',329728,0,0,0,256,0,4,0,0,0,0,0,0,0,0,70425);
